const D={"modules": [["Foundations", "Indigenous identity is not a single ethnicity or lifestyle. Self-identification, community belonging and historical continuity matter; legal definitions vary.", "Compare a nation’s own description with a government classification.", "https://social.desa.un.org/issues/indigenous-peoples"], ["Global atlas", "Territories may overlap and change over time. Modern borders do not necessarily reflect Indigenous homelands.", "Explore the atlas and consult nation-led maps.", "https://native-land.ca/"], ["Before colonization", "The Americas contained diverse cities, agricultural systems, trade networks and political institutions before European colonization.", "Compare Cahokia, Andean road networks and Pueblo architecture.", "https://americanindian.si.edu/nk360"], ["Colonization", "Colonial expansion involved distinct combinations of land seizure, coercion, settlement, forced labor and assimilation.", "Distinguish the Doctrine of Discovery from specific national laws.", "https://www.archives.gov/milestone-documents/indian-removal-act"], ["History and resistance", "Indigenous resistance includes diplomacy, litigation, cultural continuity, organizing and armed resistance.", "Explore the timeline and identify whose accounts are represented.", "https://americanindian.si.edu/nk360"], ["Governance", "Governance varies across nations; confederacies, clan responsibilities and elected institutions can coexist.", "Read the Haudenosaunee Confederacy’s own account.", "https://www.haudenosauneeconfederacy.com/"], ["Philosophy", "Reciprocity and relational responsibility appear in some Indigenous knowledge systems, but no worldview is universal.", "Reflect on the difference between learning and claiming another culture’s teachings.", "https://www.culturalsurvival.org/"], ["Ethnobotany", "Ethnobotany studies relationships between people and plants, including cultivation, food and medicine. Public knowledge is not necessarily permission to commercialize it.", "Investigate a publicly documented crop without treating medicinal uses as clinical advice.", "https://localcontexts.org/"], ["Ethnozoology", "Human relationships with animals differ across communities and include subsistence, kinship, symbolism and stewardship.", "Compare contexts without imposing a single ethical framework.", "https://www.culturalsurvival.org/"], ["Ecological knowledge", "Place-based knowledge can include seasonal indicators, fire stewardship and water management. It is dynamic and locally governed.", "Explore Indigenous-led land management rather than copying techniques out of context.", "https://www.fao.org/indigenous-peoples/en/"], ["Food sovereignty", "Food sovereignty concerns the ability of peoples to shape their own food systems. Seed saving, access to land and traditional harvesting can be central.", "Explore a community-led food initiative.", "https://www.firstnations.org/"], ["Languages", "Language revitalization can involve immersion schools, community archives and intergenerational teaching.", "Find a language program run by its speakers.", "https://www.fpcc.ca/"], ["Arts and daily life", "Indigenous arts include contemporary film, literature, design and music as well as inherited practices.", "Learn from an artist’s own explanation of their work.", "https://americanindian.si.edu/"], ["Gender and kinship", "Matrilineal descent, women’s leadership and gender roles vary across nations. Two-Spirit is a culturally specific umbrella term, not a universal label.", "Distinguish descent, residence and political authority.", "https://www.culturalsurvival.org/"], ["Trauma and healing", "Forced assimilation and family separation can have enduring effects. Community-led healing and cultural revitalization are equally important to study.", "Read survivor testimony only where publicly shared.", "https://nctr.ca/"], ["Contemporary challenges", "Land conflicts, extractive industries and unequal access to services affect many communities in different ways.", "Read a community’s own account of its priorities.", "https://www.iwgia.org/"], ["Rights and sovereignty", "The UN Declaration on the Rights of Indigenous Peoples addresses self-determination, culture, lands and consent. Domestic legal implementation varies.", "Read the declaration and distinguish it from domestic legislation.", "https://social.desa.un.org/issues/indigenous-peoples/united-nations-declaration-on-the-rights-of-indigenous-peoples"], ["Voices and contributions", "Indigenous people are contemporary scientists, writers, artists, leaders and educators.", "Choose an Indigenous-authored work and learn its context.", "https://www.culturalsurvival.org/"], ["Reconnection", "The project’s theme is responsibility toward ourselves, other people, animals and Earth. This is an editorial framing, not a universal Indigenous teaching.", "Identify a concrete responsibility in your own community.", "https://www.fao.org/indigenous-peoples/en/"], ["Education into action", "Useful allyship starts with listening to community-defined priorities, respecting consent and supporting Indigenous-led initiatives.", "Find an organization and review its stated needs.", "https://www.firstnations.org/"]], "regions": {"North America": ["Cherokee", "Lakota", "Hopi", "Diné", "Haudenosaunee"], "Central America": ["Maya", "Nahua", "Guna", "Lenca"], "South America": ["Awá", "Yanomami", "Quechua", "Aymara", "Mapuche", "Guarani"], "Europe": ["Sámi"], "Africa": ["San", "Maasai", "Batwa", "Amazigh", "Ogiek"], "Asia": ["Ainu", "Adivasi communities", "Orang Asli", "Indigenous Taiwanese peoples"], "Arctic": ["Inuit", "Nenets", "Chukchi", "Yupik"], "Oceania": ["Māori", "Aboriginal Australian nations", "Torres Strait Islanders", "Kanak"]}, "profiles": {"Cherokee": "Distinct Cherokee governments and communities continue today, including the Cherokee Nation, Eastern Band and United Keetoowah Band.", "Lakota": "Lakota communities are part of the broader Oceti Sakowin; sovereignty and treaty relationships remain important.", "Hopi": "Hopi communities in the US Southwest maintain distinct village traditions and governance.", "Diné": "The Diné, also known as Navajo, have a contemporary sovereign government and a living language.", "Haudenosaunee": "A confederacy of nations with longstanding diplomatic and governance traditions.", "Awá": "This entry refers to the Awá of the Brazilian Amazon; other peoples also use the name Awá. Avoid sensitive location information.", "Māori": "The Indigenous people of Aotearoa New Zealand, with diverse iwi and hapū.", "Sámi": "Indigenous peoples across northern Norway, Sweden, Finland and Russia, with multiple Sámi languages.", "Ainu": "Indigenous people associated with northern Japan and surrounding historical regions.", "Inuit": "Distinct Inuit communities across Arctic regions, with diverse languages and political institutions."}, "events": [["1493", "Inter Caetera", "Papal bull associated with European claims to overseas lands."], ["1763", "Royal Proclamation", "British colonial proclamation addressing land and relations with Indigenous nations."], ["1830", "Indian Removal Act", "US legislation authorizing removal agreements."], ["1838–1839", "Cherokee Trail of Tears", "Forced Cherokee displacement to Indian Territory."], ["1876", "Battle of Little Bighorn", "Conflict involving Lakota, Northern Cheyenne and US forces."], ["1887", "Dawes Act", "US allotment policy divided communal tribal lands."], ["1890", "Wounded Knee Massacre", "US troops killed Lakota people at Wounded Knee."], ["1924", "Indian Citizenship Act", "Extended US citizenship to Native Americans not already citizens."], ["1973", "Wounded Knee occupation", "Activism centered on treaty rights and grievances."], ["2007", "UNDRIP", "UN General Assembly adopted the Declaration on the Rights of Indigenous Peoples."]], "resources": [["National Museum of the American Indian", "https://americanindian.si.edu/"], ["Cultural Survival", "https://www.culturalsurvival.org/"], ["IWGIA", "https://www.iwgia.org/"], ["Native Land Digital", "https://native-land.ca/"], ["Survival International", "https://www.survivalinternational.org/"], ["First Nations Development Institute", "https://www.firstnations.org/"], ["Local Contexts", "https://localcontexts.org/"], ["Global Indigenous Data Alliance", "https://www.gida-global.org/"], ["National Centre for Truth and Reconciliation", "https://nctr.ca/"], ["UN Indigenous Peoples", "https://social.desa.un.org/issues/indigenous-peoples"]]};

