const routes=['Home','Learn','Atlas','Timeline','Knowledge','Voices & media','Rights & action','Library','Calendar','Games','Glossary','Stories of Creation','About'];let route='Home',region='All',done=[];function restoreRoute(){const p=new URLSearchParams(location.hash.slice(1));route=p.get('page')==='Peoples'?'Atlas':p.get('page')==='Quiz'?'Games':routes.find(r=>r===p.get('page'))||'Home';region=Object.keys(D.regions).includes(p.get('region'))?p.get('region'):'All'}function saveRoute(){const p=new URLSearchParams({page:route});if(route==='Peoples'&&region!=='All')p.set('region',region);const h='#'+p.toString();if(location.hash!==h){try{history.pushState(null,'',h)}catch(error){try{location.hash=h}catch(ignored){/* sandbox may prohibit URL changes */}}}}restoreRoute();function syncRoute(){restoreRoute();$('search').value='';setMenu(false);render();window.scrollTo(0,0)}window.addEventListener('popstate',syncRoute);window.addEventListener('hashchange',syncRoute);try{done=JSON.parse(localStorage.getItem('maqeena-progress')||localStorage.getItem('rootscape-progress')||'[]')}catch(e){};
const card=(t,b)=>`<article class="card"><h3>${esc(t)}</h3>${b}</article>`;const grid=a=>`<div class="grid">${a.join('')}</div>`;const btn=(r,t=r)=>`<button data-route="${esc(r)}">${esc(t)}</button>`;
