function eventDate(c,y){if(c[0]==='10-2MON'){let d=new Date(y,9,1);return new Date(y,9,1+(8-d.getDay())%7+7)}let [m,d]=c[0].split('-').map(Number);return new Date(y,m-1,d)}
function awarenessPreview(date){const now=new Date(date.getFullYear(),date.getMonth(),date.getDate());const events=CAL.flatMap(c=>[now.getFullYear(),now.getFullYear()+1].map(y=>({c,d:eventDate(c,y)}))).sort((a,b)=>a.d-b.d);const today=events.filter(x=>!monthEvent(x.c)&&+x.d===+now);const active=events.filter(x=>monthEvent(x.c)&&x.d.getFullYear()===now.getFullYear()&&x.d.getMonth()===now.getMonth());if(today.length)return {label:'TODAY',items:today,active};if(active.length)return {label:'THIS MONTH IN ADVOCACY',items:active,active:[]};const next=events.find(x=>x.d>now);return {label:'NEXT OBSERVANCE',items:next?events.filter(x=>+x.d===+next.d):[],active:[]};}
function calendarSpot(){const a=awarenessPreview(new Date());const details=x=>`<h3>${esc(x.c[1].replace(' Month begins',' Month'))}</h3><small>${monthEvent(x.c)?'All of '+x.d.toLocaleDateString(undefined,{month:'long'}):x.d.toLocaleDateString(undefined,{month:'long',day:'numeric'})} · ${esc(x.c[2])}</small>`;return `<section class="calendar-spot"><div><span class="kicker">📅 ${a.label}</span>${a.items.map(details).join('')}${a.active.length?`<div style="margin-top:.65rem"><small>ALSO THIS MONTH</small>${a.active.map(details).join('')}</div>`:''}</div>${btn('Calendar','Full calendar ↗')}</section>`}
