const impact=()=>`<section class="impact"><span class="eyebrow">The living world cannot wait</span><h2>Since you opened this page…</h2><div class="grid">${[ ['deforest','Global deforestation','10.9 million ha/year'],['netloss','Net global forest area loss','4.12 million ha/year'] ].map(x=>`<article class="card"><strong class="counter" id="${x[0]}">0</strong><p>m² · ${x[1]}</p><small>${x[2]}</small></article>`).join('')}</div><p class="muted">Illustrative estimates based on FAO 2015–2025 annual averages. Not live observations or Indigenous-specific land loss. These measures overlap; do not add them.</p>${link('https://www.fao.org/interactive/2025/forest-resources-assessment/en/','FAO Global Forest Resources Assessment 2025')}</section>`;
