const homeQuestions=[["🌎", "All cultures are alike", "Indigenous peoples are distinct nations and communities, not a single culture.", "Languages, political institutions and relationships with land vary.", "Can one map represent everyone?", "No. Maps are starting points, not definitive boundaries.", "https://americanindian.si.edu/nk360", "https://native-land.ca/"], ["📜", "Colonization is over", "Colonial policies can have continuing effects on land, language and governance.", "Understanding contemporary rights requires historical context.", "What rights are recognized internationally?", "UNDRIP addresses self-determination, lands and culture.", "https://social.desa.un.org/issues/indigenous-peoples", "https://www.un.org/development/desa/indigenouspeoples/declaration-on-the-rights-of-indigenous-peoples.html"], ["🗣️", "Languages no longer matter", "Language revitalization supports cultural continuity and community priorities.", "Languages carry distinct ways of communicating and recording knowledge.", "Can I learn a language respectfully?", "Use speaker-led resources and follow community guidance.", "https://www.unesco.org/en/decades/indigenous-languages", "https://www.firstvoices.com/"], ["🌿", "Nature is separate from us", "Human health and livelihoods depend on functioning ecosystems.", "Food, water and climate regulation connect human societies to ecological processes.", "What does biodiversity contribute?", "It supports ecosystem functions and many benefits people rely on.", "https://www.ipbes.net/global-assessment", "https://www.cbd.int/"], ["🔬", "Traditional knowledge is not science", "Indigenous knowledge systems can include systematic observation and testing, while differing from academic science.", "Knowledge systems should be understood on their own terms, with consent.", "Can knowledge be shared freely?", "Public access does not erase cultural protocols.", "https://doi.org/10.5751/ES-07008-190432", "https://localcontexts.org/"], ["🐾", "Animals are just resources", "Many non-human animals exhibit complex behavior and evidence of sentience.", "Human relationships with animals vary across societies; ethical questions deserve careful attention.", "What is sentience?", "The capacity for subjective experience, including feelings.", "https://doi.org/10.1016/j.anbehav.2016.08.013", "https://sites.google.com/nyu.edu/nydeclaration/declaration"], ["🏺", "Ancient means primitive", "Archaeological period labels describe regional material traditions, not human worth or intelligence.", "Complex social and technological systems existed in many forms.", "Are Stone Age labels universal?", "No. Regional histories differ.", "https://humanorigins.si.edu/", "https://americanindian.si.edu/nk360"], ["⚖️", "Everyone can use cultural knowledge", "Access is not the same as permission to reuse cultural materials.", "Indigenous data sovereignty and cultural protocols matter.", "Who decides appropriate use?", "The relevant community and rights holders.", "https://localcontexts.org/", "https://www.gida-global.org/"], ["🌳", "One person cannot help", "Individual actions can support collective and community-led initiatives.", "Listen to priorities set by communities rather than imposing solutions.", "Where can I start?", "Explore Indigenous-led organizations and their stated needs.", "https://www.culturalsurvival.org/", "https://www.firstnations.org/"]];
function questionSection(){return `<section class="question-section"><span class="kicker">QUESTION THE ASSUMPTION</span><h2>Question everything.</h2><p>What have we been taught to believe? Choose a topic, explore the evidence and reconsider the assumptions that keep us disconnected.</p><div class="question-grid">${homeQuestions.map((x,i)=>`<button data-question="${i}" aria-expanded="false"><span>${x[0]}</span><strong>${esc(x[1])}</strong><em>+</em></button>`).join('')}</div><div id="question-answer" hidden></div></section><section class="root-quote"><span aria-hidden="true">“</span><blockquote>Respect for the Earth is respect for the future.</blockquote><p>— Oren Lyons, Onondaga Nation Faithkeeper · ${link("https://hwpi.harvard.edu/files/hpaied/files/oren_lyons_speech_excerpted.pdf","Read the speech")}</p></section>`}
document.addEventListener('click',e=>{let b=e.target.closest('[data-question],[data-question-close]');if(!b)return;let panel=document.getElementById('question-answer');if(!panel)return;let open=b.hasAttribute('data-question')&&b.getAttribute('aria-expanded')!=='true';document.querySelectorAll('[data-question]').forEach(x=>{x.setAttribute('aria-expanded','false');x.querySelector('em').textContent='+'});panel.hidden=!open;if(!open)return;b.setAttribute('aria-expanded','true');b.querySelector('em').textContent='−';let x=homeQuestions[+b.dataset.question];panel.innerHTML=`<button class="study-btn" data-question-close>← Back</button><span class="kicker">QUICK ANSWER</span><h3>${esc(x[1])}</h3><p>${esc(x[2])}</p><div class="question-deeper"><span class="kicker">THE DEEPER ISSUE</span><p>${esc(x[3])}</p></div><h4>Common follow-up</h4><details class="myth-reveal"><summary>${esc(x[4])}</summary><p>${esc(x[5])}</p></details><h4>Explore the sources</h4><p>${link(x[6],'Read more')} · ${link(x[7],'Further resources')}</p>`;panel.scrollIntoView({block:'nearest',behavior:'smooth'})});


const creationStories=[["Lakota", "Mother Earth and the beginning of life", "Albert White Hat Sr. • Our origin story", "At first there was darkness, and Íŋyaŋ, the stone, was soft. In bringing creation into being, the stone gave its own blood. Land and water came into existence, and the blue of creation became the sky. Earth later asked for a covering; in exchange, Earth would sustain the living beings that covered her. Plants and animals came into being, and humanity followed.", "How does this account connect creation with sacrifice and responsibility?", "https://blogs.nwic.edu/teachinglearning/files/2016/04/NWIC-Tribal-Leadership-Curriculum-March-1-2010.pdf", "Read Albert White Hat Sr.’s telling"], ["Lakota", "The Sun, Moon and balance", "Albert White Hat Sr. • A second passage of the same origin story", "Earth needed warmth and light, so the stone brought forth the Sun. When the brightness and heat became too much, the Moon was created, bringing night and restoring balance. Wind followed, giving living beings breath. This episode belongs to the same origin narrative as the creation of Earth; it is not a separate account of sky people transporting the Moon.", "What does the relationship between light and darkness suggest about balance?", "https://blogs.nwic.edu/teachinglearning/files/2016/04/NWIC-Tribal-Leadership-Curriculum-March-1-2010.pdf", "Read the original telling"], ["Oneida • Haudenosaunee", "Sky Woman and Turtle Island", "Amos Christjohn • Oneida Nation", "Water covered the lower world. A woman fell from the Sky World after a hole opened near a great tree. Birds helped her reach safety on a turtle. Several animals attempted to retrieve earth from beneath the water; the muskrat finally returned with a little soil. Sky Woman combined it with what she had carried from above and placed it on the turtle, where the land grew. Her daughter and later twin grandsons continued the story of creation; the twins shaped different features of the living world.", "What roles do the animals play in making a shared home possible?", "https://oneida-nsn.gov/our-ways/creation-story/", "Read Amos Christjohn’s full account"], ["Hopi", "Emergence into the Fourth World", "Hopi Cultural Preservation Office • public overview", "Hopi teachings describe emergence from earlier worlds into the present Fourth World. The emergence establishes responsibilities to the land and to other beings. Traditions differ among clans; some knowledge is held privately and is not for general publication. This entry intentionally provides only a public overview rather than a ceremonial retelling.", "How can learners respect boundaries around knowledge entrusted to particular communities?", "https://cwis.org/2008/07/traditional-knowledge/", "Read the public cultural overview"], ["Māori", "Earth Mother and Sky Father", "Te Ahukaramū Charles Royal • Te Ara", "Ranginui, the sky father, and Papatūānuku, the earth mother, were together, with their children living in darkness between them. The children separated their parents, making room for light. Their descendants are associated with the forests, seas, winds and other parts of the natural world. Different iwi preserve distinct versions of these traditions.", "How does genealogy express relationships between people and the natural world?", "https://teara.govt.nz/en/maori-creation-traditions", "Read Māori creation traditions"]];
const nameStory=()=>`<section class="chapter origin-intro"><span class="kicker">OUR NAME</span><h2>The Story Behind Maqeena</h2><p>Maqeena is a coined name inspired by the Lakota words Makȟá (Earth) and Iná (mother). It is not a traditional Lakota word or an official translation. Its inspiration is Mother Earth and the Lakota origin account in which the Sun brings warmth, the Moon restores balance and wind brings breath.</p><p>Maqeena is a free, open-source educational project devoted to Indigenous peoples, living cultures, ancestral knowledge and sovereignty. Its purpose is to help learners discover Indigenous voices, not to speak for them.</p><p><strong>Many Peoples. Many Stories. One Earth.</strong></p><p class="fine">The name and its linguistic inspiration have not been community-reviewed or legally cleared.</p></section>`;
const creationCard=(r,i)=>`<article class="card origin-card" id="creation-${i}"><span class="kicker">${esc(r[0])}</span><h3>${esc(r[1])}</h3><p class="fine">${esc(r[2])} · ${i===3?'Public overview':'Editorial retelling'}</p><details><summary>Read the story</summary><p>${esc(r[3])}</p><p><strong>Reflect:</strong> ${esc(r[4])}</p></details><p>${link(r[5],r[6])}</p></article>`;
const creationPage=()=>`${intro('MANY PEOPLES • MANY STORIES • ONE EARTH','Stories of Creation','Discover Mother Earth, the Sun and Moon, Turtle Island and other Indigenous origin traditions.',0)}<p>Explore distinct origin traditions through named storytellers and Indigenous or educational sources. These are brief editorial retellings, not verbatim transcripts or community-approved versions. Follow the sources for the fuller accounts. These cultural narratives are not presented as astronomical or geological evidence.</p><p class="fine">Respect seasonal, ceremonial and community restrictions. Public access is not permission to reproduce a story. The project has not obtained community review or republication permission for source texts.</p>${grid(creationStories.map(creationCard))}<section class="chapter"><h2>Continue learning</h2><p>${link('https://www.si.edu/object/siris_sil_1009609','Albert White Hat Sr., Life’s Journey—Zuya (2012), chapter 3')}</p><p>${link('https://www.oneidaindiannation.org/the-haudenosaunee-creation-story','Another Oneida account of Sky Woman')}</p><p>${link('https://teara.govt.nz/en/papatuanuku-the-land','Papatūānuku — the land')}</p></section>`;
const creationHome=()=>`<section class="chapter origin-intro"><article class="card"><span class="kicker">MANY PEOPLES • MANY STORIES • ONE EARTH</span><h2>Stories of Creation</h2><p>Discover Mother Earth, the Sun and Moon, Turtle Island and other Indigenous origin traditions.</p><a href="#page=Stories%20of%20Creation" data-route="Stories of Creation">Explore creation stories ↗</a></article></section>`;

const home=()=>`<section class="manifesto5">${pic(0,'Misty green mountain landscape')}<div class="herooverlay"><span class="kicker">🌎 ONE PLANET • ONE SHARED FUTURE</span><h1>Humanity’s fundamental crisis is <em>disconnection.</em></h1><p>From ourselves. From each other. From our animal brothers and sisters. From Mother Earth.</p><p class="manifesto-urgency">Until we recognize that disconnection, the destruction will continue.</p><div class="actions">${btn('Learn','🌱 Begin your journey')}${btn('Voices & media','▶ Watch & learn')}</div></div></section><section class="impact5"><div><span class="kicker">● EVERY SECOND COUNTS</span><h2>Since you opened this page...</h2><p>While you read these words, forests are being lost.</p></div><div class="metrics5"><div><span>🌳 Global deforestation</span><strong id="deforest" class="counter">0</strong><small>square metres · approximately 3,454 m² every second</small></div><div><span>🌍 Net forest area loss</span><strong id="netloss" class="counter">0</strong><small>square metres</small></div></div><p class="fine">Continuously animated from elapsed time; capped at one annual estimate. These estimates overlap; do not add them. Not specific to Indigenous territories. ${link('https://www.fao.org/interactive/2025/forest-resources-assessment/en/','FAO source and methodology ↗')}</p></section>${calendarSpot()}${creationHome()}<section class="chapter"><span class="kicker">01 / RECONNECT</span><h2>Everything is connected.</h2><div class="visualgrid four">${tile(1,'🧠','Ourselves','Reflect on our relationship with the living world.','Learn')}${tile(2,'🤝','Each other','Explore culture, community and human diversity.','Peoples')}${tile(3,'🐾','Non-human animals','Discover animal life and our shared ecosystems.','Learn')}${tile(4,'🌎','Mother Earth','Explore ecology, biodiversity and stewardship.','Knowledge')}</div></section><section class="chapter cinema4"><div class="sectionhead"><div><span class="kicker">04 / LISTEN</span><h2>Stories beyond the textbook.</h2><p>Films, audio and Indigenous perspectives.</p></div>${btn('Voices & media','All films ↗')}</div>${filmRail()}</section>${questionSection()}<section class="chapter"><span class="kicker">📚 KEEP EXPLORING</span><h2>Read. Listen. Watch.</h2><p>Discover books, podcasts, documentaries and educational video channels.</p>${btn('Library','Explore the resource library ↗')}</section><section class="chapter"><span class="kicker">05 / QUESTION</span><h2>When harm becomes normal.</h2>${harm()}</section><section class="closing4"><span class="kicker">06 / ACT</span><h2>Understanding is only<br><em>the beginning.</em></h2><p>Learn from Indigenous peoples. Respect their sovereignty. Support Indigenous-led work.</p>${btn('Rights & action','Find ways to support ↗')}</section>`;
const YEAR=365.25*86400;const counterFormat=new Intl.NumberFormat();let lastPaint=-Infinity;
function updateImpact(now=performance.now()){const elapsed=Math.min(YEAR, Math.max(0,(Date.now()-startTime)/1000));for(const [id,rate] of [['deforest',10.9e6],['netloss',4.12e6]]){const el=$(id);if(el){const value=Math.min(rate*10000,Math.floor(elapsed*rate*10000/YEAR));el.textContent=counterFormat.format(value)}}}
function animateImpact(t){if(t-lastPaint>=32){updateImpact(t);lastPaint=t}if(Date.now()-startTime<YEAR*1000)requestAnimationFrame(animateImpact);else updateImpact(t)}requestAnimationFrame(animateImpact);

